(()=>{"use strict";const e=document.getElementById("privacy-notice"),t=document.getElementById("privacy-ack");if(!e||!t)return;let c=!1;try{c=localStorage.getItem("limu-crm-privacy")==="ack"||localStorage.getItem("limu-crm-privacy-seen")==="1"}catch{}e.hidden=c,t.addEventListener("click",()=>{e.hidden=!0;try{localStorage.setItem("limu-crm-privacy","ack")}catch{}})})();
